const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
const W=960,H=540,worldW=3060,groundY=454;
const ui={screen:document.querySelector('#screen'),hud:document.querySelector('#hud'),score:document.querySelector('#score'),lives:document.querySelector('#lives'),coop:document.querySelector('#coop'),bossbar:document.querySelector('#bossbar'),bossfill:document.querySelector('#bossfill'),toast:document.querySelector('#toast'),touch:document.querySelector('#touch')};
const keys=new Set();let mode='menu',solo=false,last=0,camera=0,score=0,toastTimer=0,shake=0,levelTime=0,particles=[],shots=[],enemyShots=[],gems=[],enemies=[],players=[],boss=null;
const platforms=[{x:285,y:376,w:155},{x:510,y:318,w:140},{x:740,y:378,w:180},{x:1015,y:330,w:155},{x:1250,y:382,w:150},{x:1480,y:318,w:170},{x:1760,y:370,w:175},{x:2020,y:310,w:165},{x:2280,y:380,w:180},{x:2480,y:340,w:145}];
function resetGame(one=false){solo=one;score=0;camera=0;levelTime=0;particles=[];shots=[];enemyShots=[];gems=[];enemies=[];players=[makePlayer(120,0),makePlayer(175,1)];
 if(solo)players.pop();
 for(let x=360;x<2460;x+=245){gems.push({x,y:280+Math.sin(x)*20,taken:false});enemies.push({x:x+65,y:groundY-34,home:x+65,vx:Math.random()>.5?35:-35,hp:1,hit:0,alive:true});}
 boss={x:2695,y:groundY-68,hp:8,max:8,mode:'idle',timer:1.5,hit:0,alive:true};
 ui.screen.classList.add('hidden');ui.hud.style.display='block';ui.touch.style.display='flex';ui.bossbar.style.display='none';ui.coop.textContent=solo?'SOLO':'2 PLAYERS';showToast('FIZZWICK MEADOWS',1800);mode='playing';
}
function makePlayer(x,id){return{x,y:groundY-56,vx:0,vy:0,w:30,h:42,id,face:1,onGround:false,shoot:0,inv:0,hearts:3,walk:0,alive:true};}
function showToast(t,d=1200){ui.toast.textContent=t;ui.toast.classList.add('on');toastTimer=d;}
document.querySelector('#play').onclick=()=>resetGame(false);document.querySelector('#solo').onclick=()=>resetGame(true);
const keyAliases={ArrowLeft:'arrowleft',ArrowRight:'arrowright',ArrowUp:'arrowup','/':'slash'};
window.addEventListener('keydown',e=>{let k=keyAliases[e.key]||e.key.toLowerCase();if(['arrowleft','arrowright','arrowup',' '].includes(k))e.preventDefault();keys.add(k);if(k==='escape'&&mode==='playing')pauseGame();if(k==='enter'&&mode==='menu')resetGame(false);});window.addEventListener('keyup',e=>keys.delete(keyAliases[e.key]||e.key.toLowerCase()));
document.querySelectorAll('.touchbtn').forEach(b=>{let k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();keys.add(k);b.setPointerCapture(e.pointerId)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>keys.delete(k));});
function pauseGame(){mode='paused';ui.screen.classList.remove('hidden');ui.hud.style.display='none';ui.touch.style.display='none';ui.screen.querySelector('.kicker').textContent='TAKE A BREATHER';ui.screen.querySelector('.logo').innerHTML='PAUSED';ui.screen.querySelector('.subtitle').textContent='The fizz will wait. Ready to jump back in?';document.querySelector('#play').textContent='BACK TO IT →';document.querySelector('#play').onclick=()=>{mode='playing';ui.screen.classList.add('hidden');ui.hud.style.display='block';ui.touch.style.display='flex';};document.querySelector('#solo').textContent='RESTART';document.querySelector('#solo').onclick=()=>resetGame(solo);}
function rect(x,y,w,h,r=0){ctx.beginPath();ctx.roundRect(x,y,w,h,r);}
function cloud(x,y,s=1){ctx.fillStyle='#fff9e6aa';ctx.beginPath();ctx.ellipse(x,y,34*s,11*s,0,0,7);ctx.ellipse(x-18*s,y+1*s,15*s,10*s,0,0,7);ctx.ellipse(x+15*s,y-6*s,18*s,14*s,0,0,7);ctx.fill();}
function drawBackground(){let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#83cbd8');sky.addColorStop(.7,'#c7e9d7');sky.addColorStop(1,'#f1e7be');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
 ctx.fillStyle='#ffe9a4';ctx.beginPath();ctx.arc(756-camera*.06,103,43,0,7);ctx.fill();ctx.fillStyle='#fff4c844';ctx.beginPath();ctx.arc(756-camera*.06,103,61,0,7);ctx.fill();
 for(let i=0;i<7;i++)cloud(((i*207-camera*.18)%(W+160)+W+160)%(W+160)-70,75+(i%3)*49,.7+(i%3)*.17);
 // soft, layered soda-cap hills
 for(let layer=0;layer<3;layer++){let base=332+layer*38,off=camera*(.13+layer*.12);ctx.fillStyle=['#a6d9bb','#83c9a6','#67ae8b'][layer];ctx.beginPath();ctx.moveTo(0,H);for(let x=-100;x<=W+100;x+=120){let wx=x+off;let y=base+Math.sin(wx*.008+layer)*25+Math.cos(wx*.016)*12;ctx.quadraticCurveTo(x+60,y-38,x+120,base+Math.sin((wx+120)*.008+layer)*25+Math.cos((wx+120)*.016)*12);}ctx.lineTo(W,H);ctx.closePath();ctx.fill();}
 // distant gumdrop trees
 for(let i=0;i<18;i++){let x=((i*173-camera*.32)%(W+100)+W+100)%(W+100)-30;let y=386+(i%3)*17;ctx.fillStyle='#557f70';ctx.fillRect(x-4,y,8,35);ctx.fillStyle=i%2?'#efa779':'#e5a989';ctx.beginPath();ctx.arc(x,y,18+(i%3)*2,0,7);ctx.fill();ctx.fillStyle='#fff3d4';ctx.beginPath();ctx.arc(x-5,y-7,4,0,7);ctx.arc(x+5,y-7,4,0,7);ctx.fill();}
}
function drawWorld(){drawBackground();ctx.save();ctx.translate(-camera,0);
 // ground
 ctx.fillStyle='#dcaa67';ctx.fillRect(0,groundY,worldW,100);ctx.fillStyle='#72bd88';ctx.fillRect(0,groundY,worldW,12);ctx.fillStyle='#a5d995';for(let x=0;x<worldW;x+=46){ctx.beginPath();ctx.ellipse(x+12,groundY+18,18,4,0,0,7);ctx.fill();}
 // tiny flowers and pebbles
 for(let x=40;x<worldW;x+=83){ctx.fillStyle=x%2?'#fff0a5':'#e99482';ctx.beginPath();ctx.arc(x,groundY+27,3,0,7);ctx.arc(x+5,groundY+30,2,0,7);ctx.fill();}
 for(const p of platforms){ctx.fillStyle='#557f70';rect(p.x,p.y,p.w,17,8);ctx.fill();ctx.fillStyle='#83d49a';rect(p.x,p.y-4,p.w,10,7);ctx.fill();ctx.fillStyle='#b9e8a4';for(let x=p.x+12;x<p.x+p.w-4;x+=25){ctx.beginPath();ctx.arc(x,p.y+5,2,0,7);ctx.fill();}}
 // signpost near boss gate
 drawSign(2385,groundY-75,'BOSS');
 for(const g of gems)if(!g.taken)drawGem(g.x,g.y,levelTime);
 for(const e of enemies)if(e.alive)drawEnemy(e);
 if(boss&&boss.alive)drawBoss();
 for(const s of shots)drawShot(s);for(const s of enemyShots)drawEnemyShot(s);
 for(const p of players)if(p.alive)drawPlayer(p);
 for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,7);ctx.fill();}ctx.globalAlpha=1;
 // exit gate, behind fight
 ctx.strokeStyle='#fff0c8';ctx.lineWidth=7;ctx.beginPath();ctx.arc(2950,groundY,38,Math.PI,0);ctx.lineTo(2988,groundY);ctx.stroke();ctx.fillStyle='#ffd768';ctx.fillRect(2947,groundY-37,6,36);ctx.restore();
}
function drawSign(x,y,text){ctx.fillStyle='#7d5942';ctx.fillRect(x,y,5,74);ctx.fillStyle='#ffcb78';rect(x-25,y-22,56,30,6);ctx.fill();ctx.strokeStyle='#173344';ctx.lineWidth=3;rect(x-25,y-22,56,30,6);ctx.stroke();ctx.fillStyle='#173344';ctx.font='900 10px Nunito';ctx.textAlign='center';ctx.fillText(text,x+3,y-3);}
function drawGem(x,y,t){let bob=Math.sin(t*4+x)*4;ctx.save();ctx.translate(x,y+bob);ctx.fillStyle='#fff2a1';ctx.beginPath();ctx.arc(0,0,14,0,7);ctx.fill();ctx.fillStyle='#ffc955';ctx.beginPath();ctx.moveTo(0,-10);ctx.lineTo(8,0);ctx.lineTo(0,10);ctx.lineTo(-8,0);ctx.closePath();ctx.fill();ctx.fillStyle='#fff';ctx.fillRect(-2,-7,3,6);ctx.restore();}

