function drawPlayer(p){ctx.save();ctx.translate(p.x+p.w/2,p.y);if(p.inv>0&&Math.floor(p.inv*14)%2)ctx.globalAlpha=.38;let bob=p.onGround?Math.sin(p.walk*12)*2:0;ctx.translate(0,bob);
 let colors=p.id?['#ec956b','#ffca7b']:['#536dcc','#a4a9ff'];let suit=colors[0],head=colors[1];
 // detached gloves and shoes, playful floating-limb silhouette
 ctx.fillStyle='#fff4db';ctx.beginPath();ctx.ellipse(-p.face*22,25,8,6,0,0,7);ctx.fill();ctx.beginPath();ctx.ellipse(p.face*22,25,8,6,0,0,7);ctx.fill();
 ctx.fillStyle='#173344';ctx.beginPath();ctx.ellipse(-9,42,9,5,0,0,7);ctx.ellipse(9,42,9,5,0,0,7);ctx.fill();
 ctx.strokeStyle=suit;ctx.lineWidth=7;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-8,29);ctx.lineTo(-11,40);ctx.moveTo(8,29);ctx.lineTo(11,40);ctx.stroke();
 ctx.fillStyle=suit;ctx.beginPath();ctx.ellipse(0,23,15,17,0,0,7);ctx.fill();ctx.fillStyle=p.id?'#ffd69b':'#d7e5ff';ctx.beginPath();ctx.ellipse(0,12,16,16,0,0,7);ctx.fill();
 // little swept hair tuft
 ctx.fillStyle=p.id?'#84433f':'#314b93';ctx.beginPath();ctx.moveTo(-12,5);ctx.quadraticCurveTo(-15,-8,-3,-5);ctx.quadraticCurveTo(8,-13,15,1);ctx.quadraticCurveTo(5,-1,1,4);ctx.closePath();ctx.fill();
 ctx.fillStyle='#173344';let eyeX=p.face*4;ctx.beginPath();ctx.ellipse(eyeX-3,12,2,3,0,0,7);ctx.ellipse(eyeX+4,12,2,3,0,0,7);ctx.fill();ctx.strokeStyle='#173344';ctx.lineWidth=1.6;ctx.beginPath();ctx.arc(eyeX,17,4,.1,Math.PI-.1);ctx.stroke();
 ctx.fillStyle=p.id?'#fff0c8':'#ffcf6a';ctx.beginPath();ctx.arc(0,24,4,0,7);ctx.fill();
 // player label
 ctx.fillStyle='#fff8e4';ctx.font='900 9px Nunito';ctx.textAlign='center';ctx.fillText(p.id?'2':'1',0,-10);
 ctx.restore();}
function drawEnemy(e){ctx.save();ctx.translate(e.x,e.y);if(e.hit>0&&Math.floor(e.hit*20)%2)ctx.globalAlpha=.45;let tilt=Math.sin(levelTime*6+e.home)*.06;ctx.rotate(tilt);
 // soda can with crimped top
 ctx.fillStyle='#153746';ctx.beginPath();ctx.ellipse(0,31,20,5,0,0,7);ctx.fill();
 ctx.fillStyle='#f26358';rect(-17,5,34,27,6);ctx.fill();ctx.fillStyle='#ffcb73';rect(-17,3,34,7,3);ctx.fill();ctx.fillStyle='#d9e7d5';rect(-15,0,30,6,3);ctx.fill();ctx.fillStyle='#173344';ctx.fillRect(-6,1,12,2);
 ctx.fillStyle='#ffdf98';ctx.beginPath();ctx.arc(0,19,9,0,7);ctx.fill();ctx.fillStyle='#173344';ctx.beginPath();ctx.arc(-3,17,1.7,0,7);ctx.arc(3,17,1.7,0,7);ctx.fill();ctx.strokeStyle='#173344';ctx.lineWidth=1.4;ctx.beginPath();ctx.arc(0,20,3,.2,Math.PI-.2);ctx.stroke();
 ctx.fillStyle='#fff3d4';ctx.font='900 7px Nunito';ctx.textAlign='center';ctx.fillText('SODA',0,10);ctx.restore();}
function drawBoss(){let b=boss;ctx.save();ctx.translate(b.x,b.y+Math.sin(levelTime*2)*3);if(b.hit>0&&Math.floor(b.hit*18)%2)ctx.globalAlpha=.4;
 // dark cloud hair, dramatic can
 ctx.fillStyle='#182a3a';ctx.beginPath();ctx.ellipse(0,9,42,40,0,0,7);ctx.ellipse(-24,17,20,29,-.3,0,7);ctx.ellipse(26,18,19,30,.3,0,7);ctx.fill();
